import { FileUpload, type FileUploadChangeDetail } from '@absoluteui/components/file-upload';
import { UploadQueue } from '@absoluteui/components/upload-queue';

const pickerHost = document.querySelector<HTMLElement>('#picker');
const queueHost = document.querySelector<HTMLElement>('#queue');
if (pickerHost && queueHost) {
  const picker = FileUpload.create(pickerHost, { label: 'Documents', multiple: true, maxFileSize: 50_000_000 });
  const queue = UploadQueue.create(queueHost, {
    label: 'Uploads',
    upload: async (file, { signal }) => {
      const response = await fetch('/api/files', { method: 'POST', body: file, signal });
      if (!response.ok) throw new Error(String(response.status));
      return response.json();
    },
  });
  picker.host.addEventListener('aui-change', (e) => {
    queue.add((e as CustomEvent<FileUploadChangeDetail>).detail.added);
    picker.setValue([]);
  });
}

import { UploadQueue, type UploadFunction } from '@absoluteui/components/upload-queue';

const CHUNK = 5_000_000;
const upload: UploadFunction = async (file, { signal, onProgress, id }) => {
  for (let offset = 0; offset < file.size; offset += CHUNK) {
    const chunk = file.slice(offset, offset + CHUNK);
    const response = await fetch(`/api/uploads/${id}?offset=${String(offset)}`, { method: 'PUT', body: chunk, signal });
    if (!response.ok) throw new Error(String(response.status));
    onProgress(Math.min(offset + CHUNK, file.size));
  }
  return null;
};

const host = document.querySelector<HTMLElement>('#queue');
if (host) UploadQueue.create(host, { label: 'Uploads', upload, concurrency: 3, retries: 2, errorMessage: () => 'The file could not be uploaded. Try again.' });
